ee:message.ee:set-payload:
%dw 2.0
import substringBefore, substringAfter from dw::core::Strings
output application/json
var queryParams = attributes.queryParams
var filters = (
    ((queryParams.FILTERS default "") splitBy ";")
        filter ((item) -> item contains ":")
        reduce ((item, acc = {}) -> acc ++ {
            (trim(item substringBefore ":")): trim(item substringAfter ":")
        })
) default {}
var limit = queryParams.LIMIT
---
{
	basePath: p("mongoDbSapi.basePath"),
	host: p("mongoDbSapi.host"),
	port: p("mongoDbSapi.port"),
	method: p('mongoDbSapi.dynamicQuery.post.method'),
	path: p('mongoDbSapi.dynamicQuery.path'),
	body: {
		"query": {
			"aggregate": "PQR_PQR",
			"pipeline": [
				{
					"\$match": {
						("_id": { "\$oid": queryParams.id }) if (!isEmpty(queryParams.id)),
						("numero_pqr": queryParams.pqrId) if (!isEmpty(queryParams.pqrId)),
						("tipo_documento": queryParams.documentType) if (!isEmpty(queryParams.documentType)),
						("numero_identificacion": queryParams.documentNumber) if (!isEmpty(queryParams.documentNumber)),
						("numero_conexion": queryParams.connectionNumber) if (!isEmpty(queryParams.connectionNumber)),
						("cuenta_facturacion": queryParams.billingAccount) if (!isEmpty(queryParams.billingAccount)),
						("cun": queryParams.cun) if (!isEmpty(queryParams.cun)),
						("usuario_asignado": filters.usuarioAsignado) if (!isEmpty(filters.usuarioAsignado)),
						("tipo_pqr": filters.tipoConsulta) if (!isEmpty(filters.tipoConsulta)),
						("servicio": filters.tipoServicio) if (!isEmpty(filters.tipoServicio)),
						("canal_recepcion": filters.canalRecepcion) if (!isEmpty(filters.canalRecepcion)),
						("dias_habiles": filters.diasHabiles) if (!isEmpty(filters.diasHabiles)),
						("estado_pqr": filters.estado) if (!isEmpty(filters.estado))
					}
				},
				({
					"\$limit": limit as Number
				}) if (!isEmpty(limit) and (limit as Number) > 0)
			],
			"cursor": {
			},
			"maxTimeMS": 5000
		}
	},
	headers: {
		"client_secret" : p('secure::api.clientSecret'),
		"client_id" : p('secure::api.clientId'),
		"name": attributes.headers.name,
		"X-CORRELATION-ID": attributes.headers."X-CORRELATION-ID" default attributes.headers."x-correlation-id" default correlationId,
		"source": attributes.headers.source,
		"systemId": attributes.headers.systemId
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
	status: 404,
	code: "NOT_FOUND",
	message: "No se encontró información para la búsqueda",
	messageServer: "",
	cause: [{
		origin: "common-papi-services-v2",
		message: "No se encontraron PQR para los criterios enviados"
	}]
}
